import{dh as l,di as s}from"./app-BE7AlBYc.js";var n="2026-10-25",p={privacy:"Политика конфиденциальности",rules:"Правила отзывов",terms:"Пользовательское соглашение",info:"Откуда сведения на сайте"},c=e=>{let[o,i,r]=e.split("-").map(Number);return new Date(o,i-1,r).toLocaleDateString("ru-RU",{day:"numeric",month:"long",year:"numeric"})};function u(e,o){let i=o.operator||"владелец сайта",r=o.email?"по электронной почте "+o.email:"через форму обратной связи владельца сайта",h=o.site||"сайт «Что приготовить?»",a="Редакция от "+c(n)+".";return e==="privacy"?{key:e,title:p.privacy,sections:[{p:[a,"Эта политика объясняет, какие данные собирает "+h+" (далее — сервис), зачем и как их удалить. Оператор персональных данных — "+i+". Обращения по вопросам данных принимаются "+r+"."]},{h:"1. Что мы не собираем",p:["Для работы сервиса не нужны телефон, электронная почта и документы. Имя (как к вам обращаться) и фото профиля — по желанию, их можно не указывать. Мы не подключаем сторонние счётчики и рекламные сети (Яндекс Метрику, Google Analytics, пиксели соцсетей) и не продаём данные."]},{h:"2. Что хранится на вашем устройстве",p:["В памяти браузера хранятся избранное, недавние рецепты, список покупок, продукты «Дома» и их сроки, морозилка, меню на неделю, «Моя книга» (что и когда вы приготовили, ваши заметки к рецептам), профиль (сколько человек едят, опыт, цели, ограничения, техника, «Соблюдаю пост», семейные даты, оформление, имя и фото, если вы их указали), дневник еды (что и сколько вы съели, калории и БЖУ), список ваших столов «Стол в складчину», оценки и отметки «нравится» и «не моё», таймеры и последние разговоры с Шефом.","Вес, рост и диагнозы мы не спрашиваем. Отметки «не едим» (например, орехи или молочное) и цель в калориях вы ставите сами — они нужны только для подбора блюд и дневника. Профиль меняется в «Профиле». Все эти данные можно удалить в «Профиле» → «Помощь и данные» → «Документы и мои данные» → «Удалить все мои данные» или очисткой данных сайта в браузере."]},{h:"3. Cookie",p:["Мы используем только технические cookie, без которых сервис не работает:","• cook_account — случайный ключ анонимного аккаунта, чтобы ваши данные были доступны на других устройствах и в семье (хранится до 400 дней);","• cook_session — временный ключ для запросов к помощнику (1 сутки);","• cook_admin — вход владельца в панель управления.","Cookie для рекламы и слежки за вами на других сайтах не используются."]},{h:"4. Анонимный аккаунт и семья",p:["При первом посещении сервис создаёт анонимный аккаунт со случайным номером. На сервере хранится копия избранного, оценок, «Моей книги» с заметками, профиля (с именем и фото, если вы их указали, оформлением, «Соблюдаю пост» и семейными датами), дневника еды и списка ваших столов «Стол в складчину» — чтобы они были доступны на других ваших устройствах; их видите только вы. Размер текста и светлая или тёмная тема остаются у каждого устройства свои.","Меню, список покупок, продукты «Дома» и морозилку видят члены семьи, которых вы пригласили. Код для входа и ключи устройств хранятся только в зашифрованном виде (хеш).","Аккаунты, в которые не заходили больше 400 дней, удаляются автоматически."]},{h:"5. Отзывы и ответы",p:["Если вы пишете отзыв или ответ, сервис сохраняет и публикует: выбранное вами имя (подпись), оценку, текст и приложенные фото. Не указывайте в подписи настоящую фамилию, если не хотите, и не публикуйте фото, на которых видны люди или личные данные.","Перед сохранением фото уменьшаются и пересохраняются: из них удаляются сведения о месте съёмки и устройстве (EXIF).","Также хранятся лайки и жалобы (без публикации, кто их поставил) и время согласия с правилами. Отзыв можно изменить или удалить в любой момент; при удалении всех данных удаляются и ваши отзывы, ответы и лайки."]},{h:"6. Статистика использования",p:["Чтобы понимать, каких рецептов не хватает и что работает плохо, сервис записывает обезличенные события: открытие рецепта, добавление в корзину, текст запроса к помощнику и нашёлся ли рецепт, тип устройства (телефон или компьютер), каким разделом воспользовались (например, «собран стол в складчину» или «запись в дневник» — без содержания записи). Вместо идентификатора браузера хранится необратимый хеш. Эти записи хранятся до 400 дней и не связываются с аккаунтом."]},{h:"6.1. Опросы «Что хотите на ужин?»",p:["Когда вы создаёте опрос, на сервере сохраняются день, названия предложенных блюд и случайная ссылка. Голосующие не указывают имён: хранится только выбранное блюдо и необратимый хеш случайного номера устройства, чтобы один человек голосовал один раз. Опрос и голоса удаляются через две недели после окончания голосования. Ссылку на опрос видит любой, кому вы её отправили."]},{h:"6.1.1. «Стол в складчину»",p:["Когда вы собираете стол, на сервере сохраняются его название, повод, день, время, место и записка, блюда и вещи, а также случайная ссылка и ключ организатора (ключ хранится в зашифрованном виде). Гости, открывшие ссылку, сами указывают имя (можно вымышленное), придут ли и сколько человек с ними, что им нельзя есть, что они берут и — если организатор включил расходы — сколько потратили. Всё это видит любой, у кого есть ссылка на стол.","Стол и ответы гостей удаляются через две недели после дня встречи (не позже чем через 200 дней после последнего изменения). Организатор может удалить стол в любой момент, он удаляется и при «Удалить все мои данные». Если организатор включил «Сообщать мне об ответах», адрес подписки его браузера хранится вместе со столом, а короткий текст («Оля придёт +1») — до показа уведомления."]},{h:"6.1.2. «Шеф в Алисе»",p:["Когда вы подключаете колонку по коду из «Профиля», мы храним необратимый хеш номера навыка на этой колонке и номер вашей семьи (сам код — тоже в виде хеша и не дольше 15 минут). Навык читает и меняет меню, список покупок и морозилку семьи по вашей просьбе голосом. Запросы обрабатывает Яндекс по своим правилам. Отключить все колонки можно в «Профиле» → «Шеф в Алисе» → «Отключить» и при «Удалить все мои данные»."]},{h:"6.1.3. Штрихкоды и калории",p:["Когда вы ищете продукт по штрихкоду, цифры штрихкода отправляются на наш сервер, а он спрашивает открытую базу Open Food Facts. Название и калорийность продукта сохраняются у нас, чтобы не спрашивать снова; с вашим аккаунтом это не связывается. Камера используется только для чтения штрихкода и ничего не записывает."]},{h:"6.2. Напоминания",p:["Если вы включили напоминания, браузер выдаёт адрес подписки в своей службе уведомлений (у Chrome и Яндекс Браузера — Google, у Firefox — Mozilla, у Safari — Apple). Мы храним этот адрес, выбранное время, часовой пояс и короткие тексты напоминаний на ближайшие дни (например, название блюда из меню). Само уведомление пустое — текст телефон берёт с нашего сервера. В приложении для Android напоминания планируются на самом телефоне и на сервер не передаются. Данные удаляются, когда вы выключаете напоминания, когда служба уведомлений сообщает, что подписка больше не действует, или через 120 дней без заходов на сайт."]},{h:"7. IP-адрес и защита от злоупотреблений",p:["IP-адрес используется только для ограничения числа попыток (вход по коду, отзывы, жалобы) и удаляется не позже чем через двое суток. Хостинг-провайдер может вести технические журналы сервера по своим правилам."]},{h:"8. Голосовой ввод",p:["Распознавание речи выполняет ваш браузер: в Chrome и на Android — сервисы Google, в Safari — Apple. Запись голоса на наш сервер не передаётся и не хранится; сервис получает только распознанный текст."+(o.serverSpeech?" Если браузер не умеет распознавать речь, запись может быть отправлена для распознавания на сервер и сразу удалена после получения текста.":"")]},{h:"8.1. Приложение для Android",p:["Приложение «Что приготовить?» для Android (RuStore) работает так же, как сайт, и пользуется тем же анонимным аккаунтом. Данные приложения хранятся в его памяти на телефоне и удаляются вместе с приложением.","Разрешения: микрофон — только для голосового ввода и голосового управления готовкой, запись идёт лишь после нажатия на микрофон или включения голосового режима; уведомления — для таймера готовки и напоминаний, которые вы включили сами; вибрация и запрет гаснуть экрану — во время готовки по шагам; камера — только когда вы сами сканируете штрихкод, фотографируете тетрадь с рецептом или ставите фото профиля. Доступа к контактам, местоположению и файлам приложение не запрашивает; фото для профиля или рецепта вы выбираете сами в окне телефона.","Речь распознаёт служба распознавания речи телефона (обычно Google или производителя телефона), текст шагов читает вслух синтезатор речи телефона. Запись голоса на наш сервер не передаётся. Таймер и напоминания планируются на самом телефоне, сервер в этом не участвует."]},...o.serverAi?[{h:"9. Помощник на сервере",p:["Чтобы лучше понять запрос, его текст (без данных аккаунта) может быть обработан моделью у подрядчика (Cloudflare Workers AI). Текст не используется для рекламы."]}]:[],{h:(o.serverAi?"10":"9")+". Цели и основания",p:["Данные обрабатываются, чтобы сервис работал (подбор рецептов, синхронизация, публикация отзывов), чтобы защищать его от спама и злоупотреблений и чтобы улучшать каталог. Основание — ваше согласие, которое вы даёте, пользуясь сервисом и отправляя отзыв, и необходимость исполнить ваш запрос."]},{h:"Ваши права",p:["Вы можете в любой момент удалить свои данные («Профиль» → «Удалить все мои данные»), выключить напоминания, изменить или удалить свои отзывы, а также запросить сведения о хранимых данных или их удаление, написав "+r+". Мы ответим в течение 10 рабочих дней.","Сервис не предназначен для детей до 14 лет: если вы младше, попросите родителей помочь с отзывами."]}]}:e==="rules"?{key:e,title:p.rules,sections:[{p:[a,"Отзывы помогают другим понять, получится ли блюдо. Пожалуйста, пишите о самом рецепте: что получилось, что поменяли, кому понравилось."]},{h:"Нельзя",p:["• оскорбления, мат, угрозы, разжигание вражды;","• реклама, ссылки, телефоны, адреса, ники в мессенджерах;","• чужие персональные данные и фото людей без их согласия;","• чужие фото и тексты без разрешения автора;","• медицинские обещания («лечит», «помогает от…») и опасные советы;","• отзывы не про это блюдо и повторяющиеся сообщения."]},{h:"Фото",p:["Прикладывайте фото своего блюда. Сведения о месте съёмки удаляются автоматически, но лица, документы и адреса в кадре мы не убираем — проверяйте снимок перед отправкой."]},{h:"Проверка",p:["Тексты с бранными словами и тексты, на которые пожаловались несколько человек, скрываются до проверки. Владелец сайта может скрыть или удалить отзыв, нарушающий правила, и закрыть автору возможность писать отзывы. Если вы считаете, что отзыв скрыт по ошибке, напишите "+r+"."]},{h:"Права на отзыв",p:["Отправляя отзыв или фото, вы подтверждаете, что вы их автор, и разрешаете бесплатно показывать их на сервисе, пока вы их не удалите."]}]}:e==="info"?{key:e,title:p.info,sections:[{p:[a,"Всё, что сервис рассказывает о блюдах и продуктах, — справочные сведения для домашней кухни. Здесь коротко о том, откуда они и как ими пользоваться."]},{h:"Рецепты",p:["Рецепты собраны редакцией сервиса из общеизвестных домашних блюд и проверяются приготовлением постепенно. Время, выход и число порций — ориентир для обычной домашней плиты и духовки; у вас может получиться быстрее или дольше."]},{h:"Изображения блюд",p:["Картинки в рецептах с пометкой «Иллюстрация» созданы нейросетью по описанию рецепта. Они показывают, как блюдо примерно может выглядеть при подаче, и не являются фотографией приготовленного по рецепту блюда. Настоящие фото блюд от людей — в отзывах."]},{h:"Калорийность и состав",p:["КБЖУ считаются автоматически по составу рецепта на основе общедоступных справочных таблиц химического состава продуктов. Реальная калорийность зависит от продуктов, их жирности и способа приготовления, поэтому цифры ориентировочные и не подходят для лечебного питания."]},{h:"Сроки хранения",p:["Сроки во вкладке «Дома», в советах про остатки и в рецептах («хранится до… дней», «можно заморозить») — типичные ориентиры из общедоступных справочных материалов для домашнего холодильника (+2…+6 °C) и морозилки (−18 °C). Они не заменяют срок годности и условия хранения, указанные производителем на упаковке. Если продукт пахнет или выглядит подозрительно — не используйте его, даже если срок ещё не вышел."]},{h:"Советы и ответы помощника",p:["Справочник повара (сколько варить, чем заменить, как понять готовность) содержит общие кулинарные советы. Помощник в чате подбирает рецепты автоматически, без участия человека, и может ошибаться — проверяйте рецепт перед тем, как готовить."]},{h:"Аллергии, дети, здоровье",p:["Исключения («без молочного», «без глютена») работают по списку продуктов рецепта и не учитывают скрытые аллергены в готовых продуктах — соусах, хлебе, колбасе, приправах. При аллергии всегда проверяйте состав на упаковке. Пометка «подходит детям» — ориентир для детей постарше; для малышей до 3 лет, беременных и людей с заболеваниями питание лучше согласовать с врачом. Сервис не даёт медицинских и диетологических рекомендаций."]},{h:"Безопасность на кухне",p:["Доводите мясо, птицу, фарш, рыбу и яйца до полной готовности, после сырого мяса мойте руки, доску и нож. Не оставляйте готовую еду при комнатной температуре дольше 2 часов, разогревайте её до горячего."]},{h:"Нашли ошибку?",p:["Если в рецепте, сроке или совете ошибка, напишите "+r+" — исправим."]}]}:{key:e,title:p.terms,sections:[{p:[a,"Пользуясь "+h+", вы соглашаетесь с этим соглашением, Политикой конфиденциальности и Правилами отзывов. Сервис бесплатный и предоставляется «как есть»."]},{h:"Рецепты и советы",p:["Рецепты, время, порции, калорийность, сроки хранения и ответы помощника — справочные и ориентировочные; откуда они взяты, рассказано на странице «Откуда сведения на сайте». Проверяйте состав на аллергены и свежесть продуктов, доводите мясо, рыбу и яйца до готовности. Информация сервиса не является медицинской или диетологической рекомендацией."]},{h:"Иллюстрации",p:["Изображения блюд в рецептах, если не отмечено иное, созданы с помощью нейросети по описанию рецепта и показывают примерную подачу. Это не фотографии блюд, приготовленных по рецепту: цвет, форма, размер порции и посуда у вас могут отличаться. Фото в отзывах загружают пользователи."]},{h:"Опросы и напоминания",p:["Опрос «Что хотите на ужин?» открыт всем, у кого есть ссылка; отправляйте её только тем, кого хотите спросить. Напоминания приходят через службу уведомлений вашего браузера или телефона, мы не гарантируем их доставку в точное время."]},{h:"Аккаунт",p:["Аккаунт анонимный. Код для входа на другом устройстве даёт полный доступ к вашим данным — не передавайте его посторонним. Если вы потеряете все устройства и код, восстановить данные будет нельзя."]},{h:"Отзывы",p:["Вы отвечаете за содержание своих отзывов и фото. Мы можем скрыть или удалить материалы, нарушающие Правила отзывов или закон."]},{h:"Ограничение ответственности",p:["Мы стараемся, чтобы сервис работал без перерывов и ошибок, но не можем это гарантировать и не отвечаем за последствия приготовления блюд по рецептам. Мы можем менять сервис и эти документы; новая редакция действует с момента публикации на сайте."]},{h:"Контакты",p:["Владелец сервиса — "+i+". Вопросы и претензии принимаются "+r+"."]}]}}var t=null;async function f(){if(t)return t;let e={operator:"",email:"",site:"сайт «Что приготовить?» ("+l().replace(/^https?:\/\//,"").replace(/\/$/,"")+")",serverAi:!1,serverSpeech:!1};try{let o=await fetch(s("legal"));if(o.ok)return t={...e,...await o.json()},t}catch{}return e}const d=p,A=()=>f(),k=(e,o)=>u(e,o);export{d as L,k as a,A as l};
